g=[[0]*26 for _ in range(22)]
# outlined rectangles: (top,left,bottom,right,color,fill)
boxes=[(1,3,6,11,1,4),(9,11,16,21,3,5),(10,2,13,5,2,8)]
for t,l,b,r,border,fill in boxes:
    for c in range(l,r+1): g[t][c]=g[b][c]=border
    for rr in range(t+1,b): g[rr][l]=g[rr][r]=border
    for rr in range(t+1,b):
        for c in range(l+1,r):
            if (rr+c)%2==0: g[rr][c]=fill
print('\n'.join(' '.join(map(str,row)) for row in g))
